Ezt akkor meg lehetne fejleszteni hogy sokkal jobban kihasznalja? import os
from flask import Flask, render_template, request, jsonify, Response
from flask_cors import CORS
import json
from cerebras.cloud.sdk import Cerebras
from exa_py import Exa
import asyncio
import aiohttp
import concurrent.futures
import time
from functools import lru_cache
import threading
import logging
from datetime import datetime, timedelta
import re
import hashlib

app = Flask(__name__)
CORS(app)

# Logging kikapcsolás a sebességért
logging.getLogger().setLevel(logging.CRITICAL)

# Gyorsítótár optimalizálás
cache = {}
cache_lock = threading.Lock()
CACHE_TTL = 7200  # 2 óra

# Kliens inicializálás - agresszív optimalizálás
client = Cerebras(
    api_key=os.environ.get("CEREBRAS_API_KEY"),
    max_retries=0,  # Nincs retry - gyorsaság
    timeout=8.0     # Rövidebb timeout
)

exa = Exa(api_key=os.environ.get("EXA_API_KEY"))

# Nagyobb thread pool a párhuzamosságért
executor = concurrent.futures.ThreadPoolExecutor(max_workers=16)

@app.route("/")
def index():
    return render_template("index.html")

def get_cache_key(message, mode):
    return hashlib.md5(f"{mode}_{message}".encode()).hexdigest()

def is_cache_valid(timestamp):
    return (datetime.now() - timestamp).total_seconds() < CACHE_TTL

@lru_cache(maxsize=1000)
def extract_keywords(text):
    words = re.findall(r'\b\w{3,}\b', text.lower())
    return list(set(words))[:8]

def create_search_queries(message):
    """Optimalizált keresési lekérdezések - kevesebb, de pontosabb"""
    keywords = extract_keywords(message)

    base_queries = [
        message,
        f"{message} tanulmány",
        f"{message} magyarország"
    ]

    if len(keywords) >= 2:
        base_queries.append(f"{' '.join(keywords[:2])}")

    return base_queries[:4]  # Csak 4 lekérdezés - gyorsaság

async def lightning_exa_search(queries, max_results=200):
    """Villámgyors EXA keresés"""
    async def search_single(query):
        try:
            loop = asyncio.get_event_loop()
            return await loop.run_in_executor(
                executor,
                lambda: exa.search(
                    query=query,
                    type="neural",
                    num_results=50,
                    include_text=["text"],
                    use_autoprompt=False  # Gyorsabb
                )
            )
        except:
            return None

    # Párhuzamos keresések - nincs késleltetés
    tasks = [search_single(query) for query in queries]
    results = await asyncio.gather(*tasks, return_exceptions=True)

    all_results = []
    seen_urls = set()

    for result in results:
        if result and hasattr(result, 'results'):
            for item in result.results:
                if item.url not in seen_urls and len(all_results) < max_results:
                    seen_urls.add(item.url)
                    all_results.append(item)

    return all_results

def extract_key_data_fast(sources):
    """Gyors kulcsadatok kinyerése"""
    key_facts = []
    statistics = []

    for source in sources[:30]:  # Csak első 30 forrás
        if not source.text:
            continue

        text = source.text[:1000]  # Rövidebb szöveg

        # Gyors statisztika keresés
        stats = re.findall(r'\d+[.,]?\d*\s*(?:%|százalék|milliárd|millió)', text)
        if stats:
            statistics.extend([(stat, source.title) for stat in stats[:2]])

        # Gyors tények
        sentences = re.split(r'[.!?]', text)
        important = [s.strip() for s in sentences[:5] 
                    if len(s.strip()) > 40 and any(word in s.lower() 
                    for word in ['szerint', 'megállapította', 'bizonyította'])]

        if important:
            key_facts.extend([(sent, source.title) for sent in important[:1]])

    return {
        'facts': key_facts[:10],
        'statistics': statistics[:8]
    }

def instant_chat_response(message):
    """Azonnali chat válasz - nincs késleltetés"""
    try:
        response = client.chat.completions.create(
            model="llama-4-scout-17b-16e-instruct",
            messages=[
                {"role": "system", "content": "Te egy gyors és pontos magyar asszisztens vagy. Rövid, lényegre törő válaszokat adsz."},
                {"role": "user", "content": message}
            ],
            max_completion_tokens=1500,
            temperature=0.8,
            top_p=0.9,
            stream=True
        )

        for chunk in response:
            if chunk.choices[0].delta.content:
                yield chunk.choices[0].delta.content

    except Exception as e:
        yield f"Hiba: {str(e)}"

def lightning_research_report(message, sources, key_data):
    """Villámgyors kutatási jelentés"""
    try:
        context = f"""
Kérdés: {message}

Források: {len(sources)} db

Statisztikák:
{chr(10).join([f"• {stat[0]}" for stat in key_data['statistics'][:3]])}

Megállapítások:
{chr(10).join([f"• {fact[0][:80]}..." for fact in key_data['facts'][:3]])}
"""

        prompt = f"""Készíts gyors, strukturált elemzést:

{context}

Formátum:
**Összefoglaló:**
[2-3 mondat]

**Főbb adatok:**
• [3-4 konkrét pont]

**Következtetés:**
[1-2 mondat]

Stílus: tömör, pontos, magyar"""

        response = client.chat.completions.create(
            model="llama-4-scout-17b-16e-instruct",
            messages=[
                {"role": "system", "content": "Gyors, strukturált elemzéseket készítesz. Tömör és pontos vagy."},
                {"role": "user", "content": prompt}
            ],
            max_completion_tokens=2000,
            temperature=0.2,
            top_p=0.8,
            stream=True
        )

        for chunk in response:
            if chunk.choices[0].delta.content:
                yield chunk.choices[0].delta.content

    except Exception as e:
        yield f"Hiba: {str(e)}"

@app.route("/chat", methods=["POST"])
def chat():
    """Villámgyors chat"""
    try:
        data = request.get_json()
        message = data.get("message", "")

        # Cache ellenőrzés
        cache_key = get_cache_key(message, "chat")
        with cache_lock:
            if cache_key in cache:
                cached_data, timestamp = cache[cache_key]
                if is_cache_valid(timestamp):
                    def serve_cache():
                        for chunk in cached_data.split(' '):
                            yield f"data: {json.dumps({'chunk': chunk + ' '})}\n\n"
                            time.sleep(0.005)  # Minimális késleltetés az olvashatóságért
                        yield f"data: {json.dumps({'done': True})}\n\n"
                    return Response(serve_cache(), mimetype='text/plain')

        def generate():
            try:
                full_response = ""
                for chunk in instant_chat_response(message):
                    full_response += chunk
                    yield f"data: {json.dumps({'chunk': chunk})}\n\n"

                # Cache mentés
                with cache_lock:
                    cache[cache_key] = (full_response, datetime.now())
                    if len(cache) > 200:
                        oldest_key = min(cache.keys(), key=lambda k: cache[k][1])
                        del cache[oldest_key]

                yield f"data: {json.dumps({'done': True})}\n\n"

            except Exception as e:
                yield f"data: {json.dumps({'error': str(e)})}\n\n"

        return Response(generate(), mimetype='text/plain')

    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route("/deepresearch", methods=["POST"])
def deep_research():
    """Villámgyors mélykeresés"""
    try:
        data = request.get_json()
        message = data.get("message", "")

        # Cache ellenőrzés
        cache_key = get_cache_key(message, "deepresearch")
        with cache_lock:
            if cache_key in cache:
                cached_data, timestamp = cache[cache_key]
                if is_cache_valid(timestamp):
                    def serve_cache():
                        for chunk in cached_data.split(' '):
                            yield f"data: {json.dumps({'chunk': chunk + ' '})}\n\n"
                            time.sleep(0.005)
                        yield f"data: {json.dumps({'done': True})}\n\n"
                    return Response(serve_cache(), mimetype='text/plain')

        def generate():
            try:
                # Gyors keresés - nincs progressbar
                queries = create_search_queries(message)

                loop = asyncio.new_event_loop()
                asyncio.set_event_loop(loop)
                sources = loop.run_until_complete(lightning_exa_search(queries, 200))
                loop.close()

                key_data = extract_key_data_fast(sources)

                # Azonnali jelentés generálás
                full_response = ""
                for chunk in lightning_research_report(message, sources, key_data):
                    full_response += chunk
                    yield f"data: {json.dumps({'chunk': chunk})}\n\n"

                # Cache mentés
                with cache_lock:
                    cache[cache_key] = (full_response, datetime.now())
                    if len(cache) > 100:
                        oldest_key = min(cache.keys(), key=lambda k: cache[k][1])
                        del cache[oldest_key]

                yield f"data: {json.dumps({'done': True})}\n\n"

            except Exception as e:
                yield f"data: {json.dumps({'error': str(e)})}\n\n"

        return Response(generate(), mimetype='text/plain')

    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, debug=False, threaded=True)
